#!/usr/bin/env node
// Verifies a repository generated by the harness.
// Usage: node scripts/verify-setup.mjs <target-dir>
import { existsSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";

const target = resolve(process.argv[2] ?? ".");
const results = [];

function check(name, fn) {
  try {
    const detail = fn();
    results.push({ name, ok: true, detail: detail || "" });
  } catch (error) {
    results.push({ name, ok: false, detail: error.message });
  }
}

function read(relative) {
  const path = join(target, relative);
  if (!existsSync(path)) throw new Error(`missing ${relative}`);
  return readFileSync(path, "utf8");
}

function noTokens(relative) {
  const content = read(relative);
  const match = content.match(/(?<!\$)\{\{[^}]+\}\}/);
  if (match) throw new Error(`unreplaced token ${match[0]} in ${relative}`);
  return "no unreplaced tokens";
}

function state() {
  return JSON.parse(read(".harness.json"));
}

const config = state();
const ciDepth = config.quality?.ciDepth;
const isFileVersion = config.version?.source === "file";
const deployTarget = config.deploy?.target ?? "none";

check(".harness.json is valid JSON with required fields", () => {
  const required = ["harness", "project", "git", "quality", "version", "release", "skills"];
  const missing = required.filter((field) => !config[field]);
  if (missing.length) throw new Error(`missing fields: ${missing.join(", ")}`);
  if (!["web", "mobile", "desktop", "library", "data"].includes(config.project.type)) {
    throw new Error(`invalid project type: ${config.project.type}`);
  }
  return `type ${config.project.type}, CI ${ciDepth}`;
});

check("AGENTS.md exists and is fully rendered", () => {
  noTokens("AGENTS.md");
  const content = read("AGENTS.md");
  if (!content.startsWith(`# ${config.project.name}`)) {
    throw new Error("AGENTS.md does not start with the project name");
  }
  const foreign = [...content.matchAll(/^##\s+(.+)$/gm)]
    .map((match) => match[1].trim())
    .filter((heading) => /^(Architecture|Tech stack|Layering|Dependencies)$/i.test(heading));
  return foreign.length
    ? `self-contained (existing project sections: ${foreign.join(", ")})`
    : "self-contained";
});

check("release template exists and is fully rendered", () => {
  noTokens("docs/RELEASE_TEMPLATE.md");
  const content = read("docs/RELEASE_TEMPLATE.md");
  const allowed = new Set(["version", "date", "summary", "from", "features", "fixes", "chores", "other"]);
  for (const match of content.matchAll(/\{([a-z_]+)\}/g)) {
    if (!allowed.has(match[1])) throw new Error(`unsupported placeholder {${match[1]}}`);
  }
  return "placeholders supported";
});

check("release engine is present", () => {
  read("scripts/release-notes.mjs");
  return "scripts/release-notes.mjs";
});

check("version tooling matches the declared source", () => {
  if (isFileVersion) {
    read("scripts/bump-version.mjs");
    const content = read(config.version.file);
    const pointer = config.version.pointer;
    const pattern = new RegExp(`${pointer}\\s*[=:]\\s*["']?[^"'\\n]+`);
    if (!pattern.test(content)) throw new Error(`${pointer} not found in ${config.version.file}`);
    return `file ${config.version.file}#${pointer}`;
  }
  read("scripts/next-version.mjs");
  return "tags only";
});

check("release workflow is present", () => {
  const content = read(".github/workflows/release.yml");
  if (!content.includes("workflow_dispatch")) throw new Error("release.yml is not manual");
  if (config.quality.checks.length && ciDepth !== "release-only" && !content.includes("ci.yml")) {
    throw new Error("release does not gate on ci.yml");
  }
  return "workflow_dispatch";
});

check("CI and build workflows match the declared depth", () => {
  if (ciDepth === "release-only") {
    if (existsSync(join(target, ".github/workflows/ci.yml"))) {
      return "ci.yml present although release-only";
    }
    return "release-only";
  }
  noTokens(".github/workflows/ci.yml");
  read(".github/workflows/ci.yml");
  if (ciDepth === "full") {
    noTokens(".github/workflows/build.yml");
    read(".github/workflows/build.yml");
  }
  return ciDepth;
});

check("deploy workflow matches the declared target", () => {
  if (deployTarget === "none") {
    if (existsSync(join(target, ".github/workflows/deploy.yml"))) {
      return "deploy.yml present although deploy is disabled";
    }
    return "disabled";
  }
  noTokens(".github/workflows/deploy.yml");
  read(".github/workflows/deploy.yml");
  return deployTarget;
});

check("workflow commands match .harness.json", () => {
  const ci = existsSync(join(target, ".github/workflows/ci.yml"))
    ? read(".github/workflows/ci.yml")
    : "";
  const build = existsSync(join(target, ".github/workflows/build.yml"))
    ? read(".github/workflows/build.yml")
    : "";
  const missing = (config.quality.checks ?? []).filter(
    (command) => !ci.includes(command),
  );
  if (missing.length) throw new Error(`checks not in ci.yml: ${missing.join("; ")}`);
  if (config.build?.command) {
    if (!`${ci}\n${build}`.includes(config.build.command)) {
      throw new Error("build command is not in ci.yml or build.yml");
    }
  }
  return `${(config.quality.checks ?? []).length} checks`;
});

check("AGENTS.md lists exactly the selected skills", () => {
  const content = read("AGENTS.md");
  for (const skill of config.skills ?? []) {
    if (!content.includes(`\`${skill}\``)) throw new Error(`skill not documented: ${skill}`);
  }
  return `${(config.skills ?? []).length} skills`;
});

check(".agent submodule exposes the selected skills", () => {
  if (!existsSync(join(target, ".agent"))) {
    return "not initialized (run git submodule update --init)";
  }
  const missing = (config.skills ?? []).filter(
    (skill) => !existsSync(join(target, ".agent/skills", skill, "SKILL.md")),
  );
  if (missing.length) throw new Error(`missing skills: ${missing.join(", ")}`);
  return "submodule ok";
});

check("gitignore covers the declared local-only patterns", () => {
  const content = existsSync(join(target, ".gitignore")) ? read(".gitignore") : "";
  const missing = (config.ignore ?? []).filter((line) => !content.split(/\r?\n/).includes(line));
  if (missing.length) throw new Error(`missing ignore entries: ${missing.join(", ")}`);
  return `${(config.ignore ?? []).length} entries`;
});

check("hygiene files match the configuration", () => {
  const hygiene = config.hygiene ?? {};
  if (hygiene.pullRequestTemplate !== false) read(".github/pull_request_template.md");
  if (hygiene.codeowners !== false) read(".github/CODEOWNERS");
  return "hygiene ok";
});

let failures = 0;
for (const result of results) {
  const status = result.ok ? "PASS" : "FAIL";
  if (!result.ok) failures += 1;
  console.log(`${status}  ${result.name}${result.detail ? ` — ${result.detail}` : ""}`);
}
console.log(`\n${results.length - failures}/${results.length} checks passed.`);
if (failures) process.exit(1);
